use lapis_app_protocol::participants::*;
use ts_rs::{Config, TS};

pub(super) fn declarations(config: &Config) -> [String; 6] {
    [
        ParticipantMessageInput::decl(config),
        ParticipantState::decl(config),
        ParticipantDelivery::decl(config),
        ParticipantMessage::decl(config),
        ParticipantCommand::decl(config),
        ParticipantValue::decl(config),
    ]
}
pub(super) fn typescript(config: &Config) -> String {
    format!(
        "// Generated by pnpm protocol:generate. Do not edit.\nimport type {{ TurnInput }} from \"./native-turn-protocol\";\nexport const PARTICIPANT_REQUEST_LIMIT = {PARTICIPANT_REQUEST_LIMIT} as const;\nexport const PARTICIPANT_RECORD_LIMIT = {PARTICIPANT_RECORD_LIMIT} as const;\n{}\n",
        declarations(config)
            .iter()
            .map(|v| format!("export {v}"))
            .collect::<Vec<_>>()
            .join("\n")
    )
}
